/// <summary>
/// Extension of UnitOfMeasure table
/// </summary>
[ExtensionOf(tableStr(UnitOfMeasure))]
public final class NDXUnitOfMeasure_tbl_Extension
{
}

Method.Source:
/// <summary>
/// Finds or creates UnitOfMeasure record by Nieda Unit record
/// </summary>
/// <param name = "_record">Niedax Unit record </param>
/// <returns>UnitOfMeasureTranslation record</returns>
static public UnitOfMeasure findOrCreateByObject(Niedax.Units.UnitRecord _record)
{
    UnitOfMeasure lUnitOfMeasure;

    System.Collections.IEnumerable unitTranslations;
    System.Collections.IEnumerator unitTranslationsEnumartor;
    Niedax.Units.UnitTxtRecord unitTxtRecord;

    if(_record != null)
    {
        UnitOfMeasureSymbol unitOfMeasureSymbol = _record.UnitId;
        lUnitOfMeasure = UnitOfMeasure::findBySymbol(unitOfMeasureSymbol, true);

        if(!lUnitOfMeasure)
        {
            lUnitOfMeasure.Symbol = unitOfMeasureSymbol;
            lUnitOfMeasure.DecimalPrecision = _record.UnitDecimals;
            lUnitOfMeasure.SystemOfUnits = _record.UnitSystem;

            lUnitOfMeasure.insert();
        }

        lUnitOfMeasure.NDXUnitLengthVariable = _record.NDX_UnitLengthVariable;
        lUnitOfMeasure.NDXLength = _record.NDX_UnitLength;

        lUnitOfMeasure.NDXUnitHeightVariable = _record.NDX_UnitHeigthVariable;
        lUnitOfMeasure.NDXHeight = _record.NDX_UnitHeigth;

        lUnitOfMeasure.NDXUnitWidthVariable = _record.NDX_UnitWidthVariable;
        lUnitOfMeasure.NDXWidth = _record.NDX_UnitWidth;

        lUnitOfMeasure.NDXUnspecifiedDimensions = _record.NDX_UnspecifiedDimensions;

        lUnitOfMeasure.NDXWeight = _record.NDX_UnitWeight;

        lUnitOfMeasure.NDXUnitMaxQty = _record.NDX_UnitMaxQty;
        lUnitOfMeasure.NDXUnitMinQty = _record.NDX_UnitMinQty;

        ttsbegin;
        lUnitOfMeasure.doUpdate();
        ttscommit;

        lUnitOfMeasure.setDescription(_record.Txt, 'de');

        unitTranslations = _record.unitTranslations;

        if(unitTranslations != null)
        {
            unitTranslationsEnumartor = unitTranslations.GetEnumerator();

            while(unitTranslationsEnumartor.MoveNext())
            {
                unitTxtRecord = unitTranslationsEnumartor.Current;
                UnitOfMeasureTranslation::findOrCreateByObject(unitTxtRecord);
            }
        }
    }

    return lUnitOfMeasure;
}

public void setDescription(str _description, LanguageId _languageId = 'de')
{
    UnitOfMeasureTranslation lUnitOfMeasureTranslation = UnitOfMeasureTranslation::findByTranslation(this.RecId, _languageId);
    lUnitOfMeasureTranslation.selectForUpdate(true);

    lUnitOfMeasureTranslation.LanguageId = _languageId;
    lUnitOfMeasureTranslation.UnitOfMeasure = this.RecId;

    if(lUnitOfMeasureTranslation.Description != _description)
    {
        lUnitOfMeasureTranslation.Description = _description;
    }

    ttsbegin;
    lUnitOfMeasureTranslation.write();
    ttscommit;

}
